/* ============================================================
   STRUCTURED LIQUIDITY — Neobrutalist structure. Liquid motion.
   Scientific modern clarity. This stylesheet IS
   the specimen.
   ============================================================ */

:root {
  /* ---- tunable knobs (driven by Tweaks) ---- */
  --accent: #a388ee; /* neobrutalism.dev purple */
  --accent-ink: #000000; /* text that sits on accent */
  --glass-blur: 14px;
  --glass-tint: 255 255 255; /* rgb channels for glass fill */
  --glass-alpha: 0.72;
  --border-w: 2px;
  --hard-x: 5px;
  --hard-y: 5px;
  --radius: 0px;
  --shell-w: 1280px;
  --content-w: var(--shell-w);
  --viewport-gutter: 4vw;
  --body-surface: var(--bg);
  --floating-ui-clearance: 96px;

  /* ---- Scientific Modern Clarity, informed by Swiss modernism and the International Typographic Style ---- */
  --text-display-xl: clamp(4.2rem, 10.5vw, 9.5rem);
  --text-display-lg: clamp(2.6rem, 5.5vw, 5.25rem);
  --measure-reading: 62ch;
  --measure-caption: 48ch;
  --grid-gutter: clamp(1rem, 2.5vw, 2.5rem);
  --section-space: clamp(4rem, 9vw, 9rem);
  --clarity-gap: clamp(1.25rem, 3vw, 3rem);
  --rule-hairline: 1px;
  --diagram-line: color-mix(in srgb, var(--ink) 72%, transparent);
  --diagram-muted: color-mix(in srgb, var(--ink) 42%, transparent);

  /* ---- light-first paper palette ---- */
  --bg: #f2f0ea;
  --bg-2: #ffffff;
  --ink: #111111; /* foreground */
  --ink-dim: #5d5d59;
  --edge: 0 0 0; /* neobrutalism black border (rgb) */
  --hard-shadow: #000000;
  --neg: #242424; /* negative / destructive surface (gray, never red) */
  --neg-ink: #ffffff;

  --display: "Inter", "Helvetica Neue", Arial, system-ui, sans-serif;
  --body: "Inter", "Helvetica Neue", Arial, system-ui, sans-serif;
  --mono: "Space Mono", "SFMono-Regular", ui-monospace, monospace;
}

/* tighter rhythm — denser, less airy */

[data-mode="light"] {
  --bg: #f2f0ea;
  --bg-2: #ffffff;
  --ink: #111111;
  --ink-dim: #5d5d59;
  --edge: 0 0 0;
  --hard-shadow: #000000;
  --neg: #16171c; /* near-black negative surface in light mode */
  --neg-ink: #ffffff;
  --glass-tint: 255 255 255;
  --glass-alpha: 0.72;
}

[data-mode="dark"] {
  /* Dark mode is color-responsive: the active accent tints the atmospheric
     field while tactile components remain charcoal. There is no black mode. */
  --bg: color-mix(in srgb, var(--accent) 18%, #100b16);
  --bg-2: color-mix(in srgb, var(--accent) 27%, #15101c);
  --ink: #f6f2f8;
  --ink-dim: #b9b0bf;
  --edge: 0 0 0;
  --hard-shadow: #000000;
  --neg: #343434;
  --neg-ink: #ffffff;
  --glass-tint: 255 255 255;
  --glass-alpha: 0.08;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: auto;
  background: var(--bg);
}

body {
  margin: 0;
  position: relative;
  background: transparent;
  color: var(--ink);
  font-family: var(--display);
  font-weight: 440;
  line-height: 1.45;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

::selection {
  background: var(--accent);
  color: var(--accent-ink);
}

/* ============================================================
   BACKDROP — flat paper plus a measured technical grid. Liquid
   belongs to interaction and continuity, not decorative scenery.
   ============================================================ */

.field {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 100%;
  z-index: -2;
  overflow: hidden;
  pointer-events: none;
  background: var(--bg);
}
[data-mode="light"] .field {
  opacity: 1;
}
[data-mode="dark"] .field {
  opacity: 1;
}

.field .grid {
  position: absolute;
  inset: 0;
  background-image:
    linear-gradient(rgba(var(--edge), 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(var(--edge), 0.045) 1px, transparent 1px);
  background-size: 64px 64px;
  opacity: 0.7;
}

.grain {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 100%;
  z-index: -1;
  pointer-events: none;
  display: none;
}

/* ============================================================
   STRUCTURAL SURFACE — flat by default. Add blur only to transient
   navigation, menus, overlays, and other moving state boundaries.
   ============================================================ */

.glass {
  position: relative;
  background: var(--bg-2);
  border: var(--border-w) solid rgb(var(--edge));
  border-radius: var(--radius);
  box-shadow: none;
}
/* moving sheen + cursor specular */
.glass::before,
.glass::after {
  content: none;
}

.flat {
  /* brutalist flat (no glass) — for loud accent blocks */
  border: var(--border-w) solid rgb(var(--edge));
  border-radius: var(--radius);
  box-shadow: var(--hard-x) var(--hard-y) 0 0 var(--hard-shadow);
}

/* ============================================================
   TYPE
   ============================================================ */

.eyebrow {
  font-family: var(--mono);
  font-size: 0.72rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ink-dim);
  display: inline-flex;
  align-items: center;
  gap: 0.6em;
}
.eyebrow::before {
  content: "";
  width: 9px;
  height: 9px;
  background: var(--accent);
  display: inline-block;
}

h1,
h2,
h3 {
  font-weight: 800;
  line-height: 0.98;
  letter-spacing: -0.02em;
  margin: 0;
  text-wrap: balance;
}

.section-title {
  font-size: clamp(2rem, 4.2vw, 4.25rem);
  line-height: 0.93;
  letter-spacing: -0.045em;
  margin: 0.25em 0 0.3em;
}
.lead {
  font-size: clamp(1rem, 1.3vw, 1.18rem);
  color: var(--ink-dim);
  max-width: 60ch;
  text-wrap: pretty;
}

.accent {
  color: var(--accent);
}
.mono {
  font-family: var(--mono);
}

/* ============================================================
   LAYOUT
   ============================================================ */

.wrap,
.shell {
  width: min(var(--shell-w), calc(100vw - var(--viewport-gutter)));
  margin-inline: auto;
}
.sl-site-content,
.sl-site-shell {
  width: min(100%, var(--shell-w));
  max-width: calc(100vw - var(--viewport-gutter));
  margin-inline: auto;
}
.sl-site-body {
  background: var(--body-surface);
}
section {
  padding: clamp(3.5rem, 8vw, 7.5rem) 0;
  position: relative;
  border-top: 1px solid color-mix(in srgb, var(--ink) 22%, transparent);
}
.section-head {
  display: grid;
  grid-template-columns: minmax(0, 5fr) minmax(280px, 4fr);
  grid-template-rows: auto auto;
  column-gap: var(--grid-gutter);
  max-width: none;
  margin-bottom: clamp(2rem, 4vw, 4rem);
}
.section-head .eyebrow {
  grid-column: 1;
  grid-row: 1;
  align-self: start;
  margin-bottom: 0.8rem;
}
.section-head .section-title {
  grid-column: 1;
  grid-row: 2;
}
.section-head .lead {
  grid-column: 2;
  grid-row: 1 / span 2;
  align-self: end;
  margin: 0;
}
@media (max-width: 720px) {
  .section-head {
    grid-template-columns: 1fr;
  }
  .section-head .eyebrow,
  .section-head .section-title,
  .section-head .lead {
    grid-column: 1;
    grid-row: auto;
  }
  .section-head .lead { margin-top: 1rem; }
}

.reveal {
  opacity: 0;
  transform: translateY(26px);
  transition:
    opacity 0.7s cubic-bezier(0.2, 0.7, 0.2, 1),
    transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.reveal.in {
  opacity: 1;
  transform: none;
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    opacity: 1;
    transform: none;
    transition: none;
  }
  html {
    scroll-behavior: auto;
  }
}

@media print {
  .reveal {
    opacity: 1 !important;
    transform: none !important;
  }
}

/* ============================================================
   STRUCTURED LIQUIDITY — component layer
   ============================================================ */

/* ---- NAV (flat structural rail; liquid is expressed by moving markers) ---- */
.nav {
  position: fixed; top: clamp(0.6rem, 1.6vw, 1rem); left: 50%; transform: translateX(-50%) translateZ(0);
  width: min(1200px, 94vw); z-index: 50;
  display: flex; align-items: center; justify-content: space-between;
  padding: 0.55rem 0.6rem 0.55rem clamp(0.9rem, 2vw, 1.3rem);
  backdrop-filter: blur(10px) saturate(150%);
  -webkit-backdrop-filter: blur(10px) saturate(150%);
  background: color-mix(in srgb, var(--bg-2) 96%, transparent);
  border: var(--border-w) solid rgb(var(--edge));
  box-shadow: none;
}
.nav .links { display: flex; gap: 1.3rem; align-items: center; }
.nav .links a {
  font-family: var(--mono); font-size: 0.78rem; letter-spacing: 0.06em;
  text-transform: uppercase; color: var(--ink-dim); text-decoration: none;
  position: relative; transition: color 0.2s;
}
.nav .links a:not(.nav-cta)::after {
  content: ""; position: absolute; left: 0; right: 0; bottom: -5px; height: 2px;
  background: var(--accent); transform: scaleX(0); transform-origin: left;
  transition: transform 0.22s ease;
}
.nav .links a.active { color: var(--ink); }
.nav .links a.active:not(.nav-cta)::after { transform: scaleX(1); }
.nav .links a:hover { color: var(--ink); }
.nav .links a.nav-cta { color: var(--accent-ink); font-family: var(--display); font-weight: 800; font-size: 0.82rem; text-transform: none; letter-spacing: -0.01em; }
.nav .links a.nav-cta:hover { color: var(--accent-ink); }
@media (max-width: 700px) { .nav .links a:not(.nav-cta) { display: none; } }

/* ---- SECTION DOT-NAV (fixed right rail) ---- */
.dotnav { position: fixed; right: clamp(0.7rem, 2vw, 1.4rem); top: 50%; transform: translateY(-50%); z-index: 60; display: flex; flex-direction: column; gap: 0.85rem; }
.dotnav a { display: flex; align-items: center; gap: 0.6rem; justify-content: flex-end; text-decoration: none; }
.dotnav .dd { width: 11px; height: 11px; flex: none; border: 2px solid rgb(var(--edge)); background: rgba(var(--glass-tint),0.12); box-shadow: 2px 2px 0 0 var(--hard-shadow); transition: background 0.2s, transform 0.15s; }
.dotnav a:hover .dd { transform: translate(-1px,-1px); }
.dotnav a.active .dd { background: var(--accent); }
.dotnav .dl { font-family: var(--mono); font-size: 0.64rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink); padding: 0.18rem 0.45rem; border: 1.5px solid rgb(var(--edge)); background: var(--bg-2); box-shadow: 2px 2px 0 0 var(--hard-shadow); opacity: 0; transform: translateX(6px); transition: opacity 0.15s, transform 0.15s; pointer-events: none; }
.dotnav a:hover .dl, .dotnav a.active .dl { opacity: 1; transform: none; }
@media (max-width: 820px) { .dotnav { display: none; } }

/* ---- LOGO GLYPH — a rigid container holding a liquid fill.
   The square + border + flat shadow = STRUCTURE; the accent
   liquid with its curved meniscus = LIQUIDITY. ---- */
.glyph {
  --s: 34px;
  width: var(--s); height: var(--s);
  position: relative; flex: none;
  border-radius: 0;
  border: 2.5px solid rgb(var(--edge));
  background: var(--bg-2);
  backdrop-filter: blur(8px) saturate(180%);
  -webkit-backdrop-filter: blur(8px) saturate(180%);
  box-shadow: 3px 3px 0 0 var(--hard-shadow);
  overflow: hidden;
}
.glyph::before {            /* the liquid fill + curved meniscus */
  content: ""; position: absolute; left: -10%; right: -10%; bottom: -8%;
  height: 58%;
  background: var(--accent);
  border-radius: 46% 46% 0 0 / 70% 70% 0 0;
  box-shadow: inset 0 2px 0 rgba(255,255,255,0.45);
}
.glyph::after { content: none; }
.glyph.lg { --s: 60px; border-width: 3px; box-shadow: 5px 5px 0 0 var(--hard-shadow); }

.brand { display: flex; align-items: center; gap: 0.7rem; text-decoration: none; color: var(--ink); }
.brand .name { font-weight: 800; font-size: 1.15rem; letter-spacing: -0.02em; }

/* ---- BUTTONS ---- */
.btn {
  font-family: var(--display); font-weight: 700; font-size: 0.98rem;
  padding: 0.85rem 1.5rem; border-radius: 0; cursor: pointer;
  display: inline-flex; align-items: center; gap: 0.6rem;
  border: var(--border-w) solid rgb(var(--edge));
  color: var(--ink); text-decoration: none;
  transition: transform 0.12s cubic-bezier(.2,.8,.2,1), box-shadow 0.12s;
  position: relative;
}
.btn.glassy {
  background: var(--bg-2);
  box-shadow: var(--hard-x) var(--hard-y) 0 0 var(--hard-shadow);
}
.btn.solid { background: var(--accent); color: var(--accent-ink); box-shadow: var(--hard-x) var(--hard-y) 0 0 var(--hard-shadow); }
.btn:active, .btn:hover { transform: translate(var(--hard-x), var(--hard-y)); box-shadow: 0 0 0 0 var(--hard-shadow); }
.btn .arrow { transition: transform 0.2s; }
.btn:hover .arrow { transform: translateX(4px); }

/* ---- HERO ---- */
.hero { padding-top: clamp(5rem, 10vh, 6.5rem); padding-bottom: clamp(2rem, 5vh, 3.5rem); min-height: auto; display: flex; align-items: center; }
.hero-grid { display: block; width: 100%; max-width: 980px; }
@media (max-width: 940px) { .hero-grid { max-width: none; } }

.wordmark {
  font-weight: 900;
  font-stretch: 125%;
  font-size: var(--text-display-xl);
  line-height: 0.84;
  letter-spacing: -0.03em;
  margin: 0.25em 0 0.3em;
  text-wrap: balance;
}
/* solid accent fallback; the enhanced word uses movement inside the letterforms */
.wordmark .glas {
  color: var(--accent);
  -webkit-text-stroke: 0;
  text-shadow: none;
}
.wordmark .brutal {
  color: var(--accent);
  position: relative;
  -webkit-text-stroke: 4px rgb(var(--edge));
  paint-order: stroke fill;
  text-shadow: var(--hard-x) var(--hard-y) 0 rgb(var(--edge));
}
.umlaut-note { font-family: var(--mono); }

/* ---- animated liquid fill (progressive enhancement via liquid-word.js) ---- */
.wordmark .glas[data-liquid].is-liquid {
  display: inline-block;
  position: relative;
  color: transparent;
  -webkit-text-stroke: 0;
  background: none;
  text-shadow: none;
}
.liquid-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
  filter: drop-shadow(var(--hard-x) var(--hard-y) 0 rgba(var(--edge), 0.3));
}
.lw-glass { fill: color-mix(in srgb, var(--accent) 20%, transparent); }
.lw-wave-back { fill: color-mix(in srgb, var(--accent) 62%, white 18%); opacity: 0.74; }
.lw-wave-front { fill: var(--accent); }
.lw-shine { fill: none; stroke: color-mix(in srgb, white 82%, var(--accent)); stroke-width: 2.5; opacity: 0.72; vector-effect: non-scaling-stroke; }
.lw-meniscus { fill: none; stroke: color-mix(in srgb, white 54%, var(--accent)); stroke-width: 5; opacity: 0.28; vector-effect: non-scaling-stroke; }
.lw-caustic { fill: none; stroke: color-mix(in srgb, white 68%, var(--accent)); stroke-width: 1.25; opacity: 0.18; vector-effect: non-scaling-stroke; }
.lw-caustic-a { animation: lw-flow 13s linear infinite reverse; }
.lw-caustic-b { animation: lw-flow 19s linear infinite; }
.lw-ripple { fill: none; stroke: color-mix(in srgb, white 55%, var(--accent)); stroke-width: 1.6; vector-effect: non-scaling-stroke; }
.lw-ripple-a { opacity: 0.32; animation: lw-flow 11s linear infinite; }
.lw-ripple-b { opacity: 0.22; animation: lw-flow 17s linear infinite reverse; }
.lw-outline { fill: none; stroke: color-mix(in srgb, rgb(var(--edge)) 82%, var(--ink)); stroke-width: 2.6; paint-order: stroke; vector-effect: non-scaling-stroke; }

.lw-slosh { transform-box: fill-box; transform-origin: center; will-change: transform; }
.lw-bob { animation: lw-bob 10s ease-in-out infinite; }
.lw-wave-front { animation: lw-flow 9s linear infinite; }
.lw-wave-back { animation: lw-flow 15s linear infinite reverse; }
.lw-shine { animation: lw-flow 9s linear infinite; }
@keyframes lw-flow {
  from { transform: translateX(0); }
  to { transform: translateX(calc(var(--w) * -1)); }
}
@keyframes lw-bob {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(calc(var(--amp, 6px) * -1)); }
}
@media (prefers-reduced-motion: reduce) {
  .lw-bob, .lw-wave-front, .lw-wave-back, .lw-shine, .lw-ripple, .lw-meniscus, .lw-caustic { animation: none; }
  .lw-slosh { transform: none !important; }
}

/* ---- hypercube logo (progressive enhancement via liquid-word.js) ---- */
.glyph.is-cube::before { content: none; }
.liquid-cube {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}
.lw-cube-innerglass { fill: color-mix(in srgb, var(--accent) 10%, transparent); }
.lw-cube-edge {
  fill: none;
  stroke: rgb(var(--edge));
  stroke-width: 1.4;
  stroke-linejoin: miter;
  stroke-linecap: butt;
  vector-effect: non-scaling-stroke;
}
.lw-cube-shell {
  fill: none;
  stroke: rgb(var(--edge));
  stroke-width: 2.4;
  stroke-linejoin: miter;
  vector-effect: non-scaling-stroke;
}

.hero-tags { display: flex; flex-wrap: wrap; gap: 0.6rem; margin: 1rem 0 1.4rem; }
.tag {
  font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.04em; text-transform: uppercase;
  padding: 0.4rem 0.8rem; border-radius: 0; border: 1.5px solid rgba(var(--edge),0.6);
  color: var(--ink-dim);
}
.hero-cta { display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; }

/* floating specimen stack in hero */
.specimen { position: relative; height: 440px; }
.specimen .card {
  position: absolute; padding: 1.3rem 1.4rem; width: 240px;
  will-change: transform;
}
.specimen .c1 { top: 0; left: 0; z-index: 1; }
.specimen .c2 { top: 122px; left: 74px; z-index: 2; }
.specimen .c3 { top: 252px; left: 22px; z-index: 3; }
.chip-row { display: flex; gap: 0.5rem; margin-top: 0.8rem; }
.dot { width: 22px; height: 22px; border-radius: 0; border: 2px solid rgb(var(--edge)); }

/* drag hint */
.draggable { cursor: grab; }
.draggable:active { cursor: grabbing; }

/* ---- TENETS (the three-tenet manifesto) ---- */
.tenets { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; align-items: stretch; }
@media (max-width: 640px) { .tenets { grid-template-columns: 1fr; } }
.tenet { padding: 1.15rem 1.2rem; display: flex; flex-direction: column; }
.tenet .pnum { font-family: var(--mono); font-size: 0.7rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--accent); }
.tenet .psub { font-family: var(--mono); font-size: 0.7rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-dim); margin-top: 0.15rem; }
.tenet h3 { font-size: 1.25rem; margin: 0.6rem 0 0.4rem; }
.tenet > p { color: var(--ink-dim); font-size: 0.9rem; margin: 0; }
.tenet ul { list-style: none; padding: 0; margin: 0.9rem 0 0; }
.tenet li { font-family: var(--mono); font-size: 0.76rem; padding: 0.4rem 0; border-top: 1px solid rgba(var(--edge),0.15); color: var(--ink-dim); display: flex; gap: 0.5rem; }
.tenet li::before { content: ""; flex: none; width: 8px; height: 8px; margin-top: 0.35em; background: var(--accent); }

/* ---- PRINCIPLES GRID ---- */
.principles { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
@media (max-width: 700px) { .principles { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 480px) { .principles { grid-template-columns: 1fr; } }
.principle { padding: 1.1rem; display: flex; flex-direction: column; min-height: 132px; }
.principle .num { font-family: var(--mono); font-size: 0.76rem; color: var(--accent); margin-bottom: auto; }
.principle h3 { font-size: 1.18rem; margin: 1rem 0 0.35rem; }
.principle p { color: var(--ink-dim); font-size: 0.88rem; margin: 0; }

/* ---- LIVE SPECIMENS ---- */
.specimens { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
@media (max-width: 640px) { .specimens { grid-template-columns: 1fr; } }
.spec-panel { padding: 1.4rem; }
.spec-label { font-family: var(--mono); font-size: 0.72rem; letter-spacing: 0.12em; text-transform: uppercase; color: var(--ink-dim); margin-bottom: 1rem; }
.spec-stage { display: flex; flex-wrap: wrap; gap: 1rem; align-items: center; }

/* toggle */
.toggle { width: 64px; height: 36px; border-radius: 0; border: var(--border-w) solid rgb(var(--edge)); position: relative; cursor: pointer;
  background: var(--bg-2);
  box-shadow: 3px 3px 0 0 var(--hard-shadow); transition: background 0.25s; }
.toggle .knob { position: absolute; top: 3px; left: 3px; width: 26px; height: 26px; border-radius: 0; background: rgb(var(--edge)); transition: transform 0.22s cubic-bezier(.3,1.4,.5,1); }
.toggle.on { background: var(--accent); }
.toggle.on .knob { transform: translateX(28px); background: var(--accent-ink); }

/* input */
.field-input { display: flex; align-items: center; gap: 0.6rem; padding: 0.7rem 1rem; border-radius: 0; min-width: 220px;
  border: var(--border-w) solid rgb(var(--edge));
  background: var(--bg-2); }
.field-input input { background: none; border: none; outline: none; color: var(--ink); font-family: var(--mono); font-size: 0.85rem; width: 100%; }
.field-input input::placeholder { color: var(--ink-dim); }
.field-input:focus-within { box-shadow: 4px 4px 0 0 var(--accent); }

/* segmented */
.seg { display: inline-flex; border: var(--border-w) solid rgb(var(--edge)); border-radius: 0; overflow: hidden; box-shadow: 3px 3px 0 0 var(--hard-shadow);
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px); background: rgba(var(--glass-tint),0.05); }
.seg button { font-family: var(--mono); font-size: 0.78rem; padding: 0.55rem 0.9rem; border: none; background: none; color: var(--ink-dim); cursor: pointer; border-left: 1px solid rgba(var(--edge),0.3); }
.seg button:first-child { border-left: none; }
.seg button.sel { background: var(--accent); color: var(--accent-ink); }

/* slider specimen */
.gslider { width: 220px; height: 36px; display: flex; align-items: center; }
.gslider .track { flex: 1; height: 8px; border-radius: 0; border: 2px solid rgb(var(--edge)); position: relative; background: rgba(var(--glass-tint),0.06); }
.gslider .fill { position: absolute; left: 0; top: 0; bottom: 0; width: 55%; background: var(--accent); border-radius: 0; }
.gslider .thumb { position: absolute; top: 50%; left: 55%; width: 22px; height: 22px; transform: translate(-50%,-50%); border-radius: 0; background: rgb(var(--edge)); border: 2px solid rgb(var(--edge)); box-shadow: 2px 2px 0 var(--hard-shadow); }

/* ---- DO / DON'T ---- */
.rules { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; }
@media (max-width: 760px) { .rules { grid-template-columns: 1fr; } }
.rule { padding: 1.4rem; }
.rule .badge { font-family: var(--mono); font-weight: 700; font-size: 0.8rem; letter-spacing: 0.1em; padding: 0.3rem 0.7rem; border-radius: 0; display: inline-block; margin-bottom: 1.2rem; }
.rule.do .badge { background: var(--accent); color: var(--accent-ink); }
.rule.dont .badge { background: transparent; border: 2px solid rgb(var(--edge)); color: var(--ink); }
.rule ul { list-style: none; padding: 0; margin: 0; }
.rule li { padding: 0.7rem 0; border-top: 1px solid rgba(var(--edge),0.15); font-size: 0.95rem; }
.rule.dont li { color: var(--ink-dim); text-decoration: line-through; text-decoration-color: rgba(var(--edge),0.3); }

/* ---- TOKENS ---- */
.tokens { display: grid; grid-template-columns: 1.2fr 1fr; gap: 1rem; }
@media (max-width: 820px) { .tokens { grid-template-columns: 1fr; } }
.swatches { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.8rem; margin-top: 1.2rem; }
.swatch { aspect-ratio: 1; border-radius: 0; border: 2px solid rgb(var(--edge)); display: flex; align-items: flex-end; padding: 0.5rem; font-family: var(--mono); font-size: 0.6rem; box-shadow: 3px 3px 0 var(--hard-shadow); }
.type-row { display: flex; align-items: baseline; gap: 1rem; padding: 0.9rem 0; border-top: 1px solid rgba(var(--edge),0.15); }
.type-row .k { font-family: var(--mono); font-size: 0.7rem; color: var(--ink-dim); width: 90px; flex: none; }

/* ---- FOOTER CTA ---- */
.cta-panel { padding: clamp(1.6rem, 3.2vw, 2.4rem); text-align: center; display: flex; flex-direction: column; align-items: center; gap: 1rem; }
.cta-panel h2 { font-size: clamp(1.8rem, 3.5vw, 3rem); }
footer { padding: 2rem 0 2.5rem; }
.foot { display: flex; justify-content: space-between; align-items: center; flex-wrap: wrap; gap: 1rem; border-top: var(--border-w) solid rgba(var(--edge),0.4); padding-top: 2rem; }
.foot .mono { font-size: 0.78rem; color: var(--ink-dim); }
.foot .foot-legal { font-size: 0.76rem; color: var(--ink-dim); text-align: right; max-width: 52ch; }
.foot .foot-legal a { color: var(--ink); text-decoration: none; border-bottom: 1px solid var(--accent); transition: color 0.2s; }
.foot .foot-legal a:hover { color: var(--accent); }
@media (max-width: 640px) { .foot .foot-legal { text-align: left; } }

/* ============================================================
   STRUCTURED LIQUIDITY — component KIT
   A shadcn-complete library expressed in the design language:
   rigid containers (sharp edges, flat offset shadows, real
   borders) holding flat scientific surfaces, with one accent
   carrying selection and liquid motion between states.
   ============================================================ */

/* ---- gallery scaffold ---- */
.kit-groups { display: flex; flex-direction: column; gap: 2.2rem; }
.kit-group > .kit-group-head { display: flex; align-items: baseline; gap: 0.8rem; margin-bottom: 1rem; }
.kit-group-head .kg-name { font-family: var(--mono); font-size: 0.78rem; letter-spacing: 0.16em; text-transform: uppercase; color: var(--ink); }
.kit-group-head .kg-rule { flex: 1; height: 2px; background: rgba(var(--edge),0.25); }
.kit-group-head .kg-count { font-family: var(--mono); font-size: 0.72rem; color: var(--ink-dim); }

.kit-grid { display: grid; grid-template-columns: repeat(12, 1fr); gap: 1rem; }
.kit-cell { padding: 1.2rem 1.25rem; display: flex; flex-direction: column; gap: 0.95rem; grid-column: span 4; min-width: 0; }
.kit-cell.w6 { grid-column: span 6; }
.kit-cell.w8 { grid-column: span 8; }
.kit-cell.w12 { grid-column: span 12; }
@media (max-width: 900px) { .kit-cell, .kit-cell.w6, .kit-cell.w8 { grid-column: span 6; } .kit-cell.w12 { grid-column: span 12; } }
@media (max-width: 600px) { .kit-cell, .kit-cell.w6, .kit-cell.w8, .kit-cell.w12 { grid-column: span 12; } }
.kit-cap { font-family: var(--mono); font-size: 0.68rem; letter-spacing: 0.14em; text-transform: uppercase; color: var(--ink-dim); display: flex; align-items: center; gap: 0.5rem; }
.kit-cap::before { content: ""; width: 7px; height: 7px; background: var(--accent); flex: none; }
.kit-row { display: flex; flex-wrap: wrap; gap: 0.6rem; align-items: center; }
.kit-col { display: flex; flex-direction: column; gap: 0.7rem; }
.kit-demo { display: flex; flex-wrap: wrap; gap: 0.7rem; align-items: center; }

/* glass + flat helpers reused locally */
.sl-glass-fill {
  background: var(--bg-2);
}

/* ============================================================
   BUTTONS — full variant matrix
   ============================================================ */
.sl-btn {
  font-family: var(--display); font-weight: 700; font-size: 0.85rem; line-height: 1;
  padding: 0.6rem 1rem; border-radius: var(--radius); cursor: pointer;
  display: inline-flex; align-items: center; justify-content: center; gap: 0.45rem;
  border: var(--border-w) solid rgb(var(--edge)); color: var(--ink); text-decoration: none;
  transition: transform 0.12s cubic-bezier(.2,.8,.2,1), box-shadow 0.12s; white-space: nowrap;
}
.sl-btn.default { background: var(--accent); color: var(--accent-ink); box-shadow: 4px 4px 0 0 var(--hard-shadow); }
.sl-btn.secondary { background: var(--bg-2); box-shadow: 4px 4px 0 0 var(--hard-shadow); }
.sl-btn.outline { background: transparent; box-shadow: 4px 4px 0 0 var(--hard-shadow); }
.sl-btn.ghost { background: transparent; border-color: transparent; box-shadow: none; color: var(--ink-dim); }
.sl-btn.ghost:hover { color: var(--ink); background: rgba(var(--glass-tint),0.08); transform: none; }
.sl-btn.destructive { background: var(--neg); color: var(--neg-ink); box-shadow: 4px 4px 0 0 var(--hard-shadow); }
.sl-btn.link { border-color: transparent; box-shadow: none; background: none; color: var(--accent); text-decoration: underline; text-underline-offset: 3px; padding: 0.6rem 0.2rem; }
.sl-btn.link:hover { transform: none; }
.sl-btn.icon { padding: 0.55rem; width: 38px; height: 38px; }
.sl-btn.sm { padding: 0.4rem 0.7rem; font-size: 0.76rem; }
.sl-btn.lg { padding: 0.8rem 1.3rem; font-size: 0.95rem; }
.sl-btn:not(.ghost):not(.link):hover, .sl-btn:not(.ghost):not(.link):active { transform: translate(4px, 4px); box-shadow: 0 0 0 0 var(--hard-shadow); }
.sl-btn[disabled] { opacity: 0.4; pointer-events: none; }
.sl-spinner { width: 13px; height: 13px; border: 2px solid currentColor; border-right-color: transparent; border-radius: 50%; animation: sl-spin 0.7s linear infinite; }
@keyframes sl-spin { to { transform: rotate(360deg); } }

/* ============================================================
   BADGE
   ============================================================ */
.sl-badge { font-family: var(--mono); font-size: 0.68rem; font-weight: 700; letter-spacing: 0.05em; text-transform: uppercase; padding: 0.28rem 0.55rem; border-radius: var(--radius); border: 1.5px solid rgb(var(--edge)); display: inline-flex; align-items: center; gap: 0.35rem; }
.sl-badge.default { background: var(--accent); color: var(--accent-ink); }
.sl-badge.secondary { background: rgba(var(--glass-tint),0.1); color: var(--ink); }
.sl-badge.outline { background: transparent; color: var(--ink-dim); }
.sl-badge.destructive { background: var(--neg); color: var(--neg-ink); border-color: rgb(var(--edge)); }
.sl-badge .ico { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }

/* ============================================================
   INPUT / LABEL / TEXTAREA / OTP
   ============================================================ */
.sl-label { font-family: var(--mono); font-size: 0.7rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-dim); }
.sl-input, .sl-textarea {
  font-family: var(--mono); font-size: 0.82rem; color: var(--ink); width: 100%;
  padding: 0.6rem 0.8rem; border-radius: var(--radius); border: var(--border-w) solid rgb(var(--edge));
  background: var(--bg-2);
  box-shadow: none; outline: none;
}
.sl-textarea { min-height: 76px; resize: vertical; line-height: 1.5; }
.sl-input::placeholder, .sl-textarea::placeholder { color: var(--ink-dim); }
.sl-input:focus, .sl-textarea:focus { box-shadow: 3px 3px 0 0 var(--accent); }
.sl-otp { display: flex; gap: 0.5rem; }
.sl-otp input { width: 42px; height: 48px; text-align: center; font-family: var(--mono); font-size: 1.1rem; font-weight: 700; color: var(--ink); border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); background: rgba(var(--glass-tint),0.06); outline: none; box-shadow: 2px 2px 0 0 var(--hard-shadow); }
.sl-otp input:focus { box-shadow: 2px 2px 0 0 var(--accent); }

/* ============================================================
   CHECKBOX / RADIO / SWITCH / TOGGLE
   ============================================================ */
.sl-check, .sl-radio-item { display: flex; align-items: center; gap: 0.6rem; cursor: pointer; font-size: 0.85rem; }
.sl-box { width: 20px; height: 20px; flex: none; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); background: rgba(var(--glass-tint),0.06); box-shadow: 2px 2px 0 0 var(--hard-shadow); display: grid; place-items: center; transition: background 0.15s; }
.sl-check[aria-checked="true"] .sl-box { background: var(--accent); }
.sl-box .tick { width: 11px; height: 11px; color: var(--accent-ink); opacity: 0; }
.sl-check[aria-checked="true"] .sl-box .tick { opacity: 1; }
.sl-radio { width: 20px; height: 20px; flex: none; border: var(--border-w) solid rgb(var(--edge)); border-radius: 50%; background: var(--bg-2); box-shadow: 2px 2px 0 0 var(--hard-shadow); display: grid; place-items: center; overflow: hidden; transition: background var(--motion-fast) var(--ease-liquid); }
.sl-radio .dot { width: 100%; height: 100%; border-radius: inherit; background: var(--accent); opacity: 0; }
.sl-radio-item[aria-checked="true"] .sl-radio .dot { opacity: 1; }
.sl-switch { width: 46px; height: 26px; border-radius: var(--radius); border: var(--border-w) solid rgb(var(--edge)); position: relative; cursor: pointer; background: rgba(var(--glass-tint),0.1); box-shadow: 2px 2px 0 0 var(--hard-shadow); transition: background 0.2s; flex: none; }
.sl-switch .knob { position: absolute; top: 2px; left: 2px; width: 18px; height: 18px; border-radius: calc(var(--radius) * 0.6); background: rgb(var(--edge)); transition: transform 0.2s cubic-bezier(.3,1.4,.5,1); }
.sl-switch[aria-checked="true"] { background: var(--accent); }
.sl-switch[aria-checked="true"] .knob { transform: translateX(20px); background: var(--accent-ink); }
.sl-toggle { font-family: var(--mono); font-size: 0.8rem; padding: 0.45rem 0.7rem; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); background: rgba(var(--glass-tint),0.06); color: var(--ink-dim); cursor: pointer; box-shadow: 2px 2px 0 0 var(--hard-shadow); }
.sl-toggle[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); }
.sl-toggle-group { display: inline-flex; gap: 0; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); overflow: hidden; box-shadow: 2px 2px 0 0 var(--hard-shadow); }
.sl-toggle-group button { font-family: var(--mono); font-size: 0.8rem; padding: 0.45rem 0.7rem; border: none; border-left: 1px solid rgba(var(--edge),0.3); background: rgba(var(--glass-tint),0.05); color: var(--ink-dim); cursor: pointer; display: grid; place-items: center; }
.sl-toggle-group button:first-child { border-left: none; }
.sl-toggle-group button[aria-pressed="true"] { background: var(--accent); color: var(--accent-ink); }
.sl-toggle-group.is-liquid { position: relative; isolation: isolate; }
.sl-toggle-group.is-liquid .sl-toggle-marker {
  position: absolute; inset-block: 0; left: 0; z-index: 0;
  width: calc(100% / var(--toggle-count));
  transform: translateX(calc(var(--toggle-index) * 100%));
  background: var(--accent);
  transition: transform var(--motion) var(--ease-liquid-over), width var(--motion) var(--ease-liquid);
  pointer-events: none;
}
.sl-toggle-group.is-liquid button { position: relative; z-index: 1; background: transparent; transition: color var(--motion-fast) var(--ease-liquid); }
.sl-toggle-group.is-liquid button[aria-pressed="true"] { background: transparent; color: var(--accent-ink); }

/* ============================================================
   SLIDER / PROGRESS
   ============================================================ */
.sl-slider { width: 100%; height: 26px; display: flex; align-items: center; }
.sl-slider .trk { flex: 1; height: 8px; border-radius: var(--radius); border: 2px solid rgb(var(--edge)); position: relative; background: rgba(var(--glass-tint),0.06); cursor: pointer; }
.sl-slider .fl { position: absolute; left: 0; top: 0; bottom: 0; background: var(--accent); }
.sl-slider .th { position: absolute; top: 50%; transform: translate(-50%,-50%); width: 18px; height: 18px; border-radius: var(--radius); background: rgb(var(--edge)); box-shadow: 2px 2px 0 var(--hard-shadow); }
.sl-progress { width: 100%; height: 14px; border: 2px solid rgb(var(--edge)); border-radius: var(--radius); background: rgba(var(--glass-tint),0.06); overflow: hidden; box-shadow: inset 0 1px 0 rgba(255,255,255,0.2); }
.sl-progress > span { display: block; height: 100%; background: var(--accent); background-image: linear-gradient(135deg, rgba(255,255,255,0.25) 25%, transparent 25%, transparent 50%, rgba(255,255,255,0.25) 50%, rgba(255,255,255,0.25) 75%, transparent 75%); background-size: 16px 16px; transition: width 0.4s; }

/* ============================================================
   SELECT / DROPDOWN / COMBOBOX / COMMAND
   ============================================================ */
.sl-pop-wrap { position: relative; }
.sl-trigger {
  font-family: var(--mono); font-size: 0.82rem; color: var(--ink); cursor: pointer;
  padding: 0.55rem 0.8rem; border-radius: var(--radius); border: var(--border-w) solid rgb(var(--edge));
  background: var(--bg-2);
  box-shadow: 2px 2px 0 0 var(--hard-shadow); display: inline-flex; align-items: center; justify-content: space-between; gap: 0.7rem; min-width: 160px;
}
.sl-trigger .chev { transition: transform 0.2s; color: var(--ink-dim); }
.sl-trigger[aria-expanded="true"] .chev { transform: rotate(180deg); }
.sl-menu {
  position: absolute; top: calc(100% + 8px); left: 0; min-width: 200px; z-index: 30;
  border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius);
  background: var(--bg-2);
  backdrop-filter: blur(18px) saturate(180%); -webkit-backdrop-filter: blur(18px) saturate(180%);
  box-shadow: 6px 6px 0 0 var(--hard-shadow); padding: 0.35rem;
  opacity: 0; transform: translateY(-6px) scale(0.98); transform-origin: top left; pointer-events: none;
  transition: opacity 0.15s, transform 0.15s;
}
.sl-menu.open { opacity: 1; transform: none; pointer-events: auto; }
/* each .glass cell is its own stacking context (backdrop-filter), so an open
   menu would otherwise be painted under later sibling cells — lift the host */
.kit-cell:has(.sl-menu.open),
.kit-cell:has(.sl-trigger[aria-expanded="true"]),
.kit-cell:has([data-pop][aria-expanded="true"]) { z-index: 40; }
.sl-menu .item { font-family: var(--mono); font-size: 0.8rem; padding: 0.5rem 0.6rem; border-radius: calc(var(--radius) * 0.6); color: var(--ink); cursor: pointer; display: flex; align-items: center; gap: 0.55rem; }
.sl-menu .item:hover, .sl-menu .item.active { background: var(--accent); color: var(--accent-ink); }
.sl-menu .item .k { margin-left: auto; font-size: 0.7rem; opacity: 0.6; }
.sl-menu .sep { height: 1px; background: rgba(var(--edge),0.2); margin: 0.3rem 0; }
.sl-menu .lbl { font-family: var(--mono); font-size: 0.64rem; letter-spacing: 0.1em; text-transform: uppercase; color: var(--ink-dim); padding: 0.4rem 0.6rem 0.2rem; }
.sl-cmd-search { font-family: var(--mono); font-size: 0.8rem; color: var(--ink); width: 100%; padding: 0.5rem 0.6rem; border: none; border-bottom: 1.5px solid rgba(var(--edge),0.3); background: none; outline: none; margin-bottom: 0.3rem; }
.sl-cmd-search::placeholder { color: var(--ink-dim); }

/* ============================================================
   TABS
   ============================================================ */
.sl-tabs .tablist { position: relative; display: inline-flex; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); overflow: hidden; box-shadow: 2px 2px 0 0 var(--hard-shadow); isolation: isolate; }
.sl-tabs .tablist button { position: relative; z-index: 1; flex: 1; font-family: var(--body); font-size: 0.78rem; font-weight: 650; padding: 0.5rem 0.9rem; border: none; border-left: 1px solid rgba(var(--edge),0.3); background: transparent; color: var(--ink-dim); cursor: pointer; transition: color var(--motion-fast) var(--ease-liquid); }
.sl-tabs .tablist button:first-child { border-left: none; }
.sl-tabs .tablist button[aria-selected="true"] { background: transparent; color: var(--accent-ink); }
.sl-tabs .sl-tab-marker {
  position: absolute; inset-block: 0; left: 0; z-index: 0;
  width: calc(100% / var(--tab-count));
  transform: translateX(calc(var(--tab-index) * 100%));
  background: var(--accent);
  transition: transform var(--motion) var(--ease-liquid-over), width var(--motion) var(--ease-liquid);
  pointer-events: none;
}
.sl-tabs .panel { display: none; padding-top: 0.9rem; font-size: 0.88rem; color: var(--ink-dim); }
.sl-tabs .panel.show { display: block; }

/* ============================================================
   ACCORDION
   ============================================================ */
.sl-acc-item { border-bottom: 1px solid rgba(var(--edge),0.18); }
.sl-acc-head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 0.8rem 0; cursor: pointer; font-weight: 700; font-size: 0.92rem; font-family: var(--display); }
.sl-acc-head .pm { width: 16px; height: 16px; position: relative; flex: none; }
.sl-acc-head .pm::before, .sl-acc-head .pm::after { content: ""; position: absolute; background: var(--accent); transition: transform 0.2s; }
.sl-acc-head .pm::before { left: 0; right: 0; top: 7px; height: 2px; }
.sl-acc-head .pm::after { top: 0; bottom: 0; left: 7px; width: 2px; }
.sl-acc-item.open .pm::after { transform: scaleY(0); }
.sl-acc-body { max-height: 0; overflow: hidden; transition: max-height 0.25s ease; }
.sl-acc-body > p { padding: 0 0 0.9rem; margin: 0; font-size: 0.85rem; color: var(--ink-dim); }

/* ============================================================
   AVATAR
   ============================================================ */
.sl-ava { width: 40px; height: 40px; border-radius: var(--radius); border: var(--border-w) solid rgb(var(--edge)); overflow: hidden; display: grid; place-items: center; font-family: var(--mono); font-weight: 700; font-size: 0.85rem; box-shadow: 2px 2px 0 0 var(--hard-shadow); background: var(--accent); color: var(--accent-ink); flex: none; }
.sl-ava img { width: 100%; height: 100%; object-fit: cover; }
.sl-ava-group { display: flex; }
.sl-ava-group .sl-ava { margin-left: -10px; box-shadow: 2px 2px 0 0 var(--hard-shadow); }
.sl-ava-group .sl-ava:first-child { margin-left: 0; }

/* ============================================================
   ALERT
   ============================================================ */
.sl-alert { display: flex; gap: 0.8rem; padding: 0.9rem 1rem; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); border-left-width: 6px; background: rgba(var(--glass-tint),0.06); }
.sl-alert.destructive { border-left-color: var(--neg); }
.sl-alert .ai { flex: none; width: 20px; height: 20px; color: var(--accent); }
.sl-alert.destructive .ai { color: var(--ink); }
.sl-alert .at { font-weight: 700; font-size: 0.9rem; margin: 0 0 0.2rem; }
.sl-alert .ad { font-size: 0.82rem; color: var(--ink-dim); margin: 0; }

/* ============================================================
   TABLE
   ============================================================ */
.sl-table { width: 100%; border-collapse: collapse; font-size: 0.82rem; }
.sl-table th { font-family: var(--mono); font-size: 0.66rem; letter-spacing: 0.08em; text-transform: uppercase; color: var(--ink-dim); text-align: left; padding: 0.55rem 0.7rem; border-bottom: 2px solid rgb(var(--edge)); }
.sl-table td { padding: 0.6rem 0.7rem; border-bottom: 1px solid rgba(var(--edge),0.15); }
.sl-table tr:last-child td { border-bottom: none; }
.sl-table tbody tr:hover { background: rgba(var(--glass-tint),0.05); }

/* ============================================================
   SKELETON
   ============================================================ */
.sl-skel { background: linear-gradient(90deg, rgba(var(--glass-tint),0.06) 25%, rgba(var(--glass-tint),0.16) 37%, rgba(var(--glass-tint),0.06) 63%); background-size: 400% 100%; animation: sl-shimmer 1.4s ease infinite; border-radius: var(--radius); border: 1px solid rgba(var(--edge),0.18); }
@keyframes sl-shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
@media (prefers-reduced-motion: reduce) { .sl-skel { animation: none; } }

/* ============================================================
   TOOLTIP / HOVER CARD
   ============================================================ */
.sl-tip-wrap { position: relative; display: inline-flex; }
.sl-tip { position: absolute; bottom: calc(100% + 8px); left: 50%; transform: translateX(-50%) translateY(4px); white-space: nowrap; font-family: var(--mono); font-size: 0.72rem; padding: 0.4rem 0.6rem; background: var(--bg-2); border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); box-shadow: 3px 3px 0 0 var(--hard-shadow); opacity: 0; pointer-events: none; transition: opacity 0.15s, transform 0.15s; z-index: 20; }
.sl-tip-wrap:hover .sl-tip { opacity: 1; transform: translateX(-50%); }
.sl-hover-card { position: absolute; top: calc(100% + 8px); left: 0; width: 240px; padding: 1rem; background: var(--bg-2); border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); box-shadow: 6px 6px 0 0 var(--hard-shadow); opacity: 0; pointer-events: none; transform: translateY(6px); transition: opacity 0.18s, transform 0.18s; z-index: 20; }
.sl-tip-wrap:hover .sl-hover-card { opacity: 1; transform: none; }

/* ============================================================
   SEPARATOR
   ============================================================ */
.sl-sep { height: 2px; background: rgba(var(--edge),0.25); border: none; width: 100%; }
.sl-sep.v { width: 2px; height: 28px; }

/* ============================================================
   BREADCRUMB / PAGINATION / MENUBAR
   ============================================================ */
.sl-crumb { display: flex; align-items: center; gap: 0.5rem; font-family: var(--mono); font-size: 0.78rem; flex-wrap: wrap; }
.sl-crumb a { color: var(--ink-dim); text-decoration: none; }
.sl-crumb a:hover { color: var(--ink); }
.sl-crumb .sl-cur { color: var(--accent); }
.sl-crumb .sl-sl { color: var(--ink-dim); opacity: 0.5; }
.sl-page { display: flex; gap: 0.4rem; }
.sl-page button { width: 36px; height: 36px; font-family: var(--mono); font-size: 0.8rem; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); background: rgba(var(--glass-tint),0.06); color: var(--ink); cursor: pointer; box-shadow: 2px 2px 0 0 var(--hard-shadow); }
.sl-page button.cur { background: var(--accent); color: var(--accent-ink); }
.sl-page button[disabled] { opacity: 0.35; pointer-events: none; }
.sl-menubar { display: inline-flex; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); box-shadow: 2px 2px 0 0 var(--hard-shadow); overflow: hidden; }
.sl-menubar > button { font-family: var(--mono); font-size: 0.78rem; padding: 0.45rem 0.8rem; border: none; border-left: 1px solid rgba(var(--edge),0.25); background: rgba(var(--glass-tint),0.05); color: var(--ink-dim); cursor: pointer; }
.sl-menubar > button:first-child { border-left: none; }
.sl-menubar > button:hover { background: var(--accent); color: var(--accent-ink); }

/* ============================================================
   CALENDAR / DATE
   ============================================================ */
.sl-cal { width: 100%; }
.sl-cal-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 0.6rem; font-family: var(--mono); font-size: 0.82rem; }
.sl-cal-head button { width: 28px; height: 28px; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); background: rgba(var(--glass-tint),0.06); color: var(--ink); cursor: pointer; }
.sl-cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 3px; }
.sl-cal-grid .dow { font-family: var(--mono); font-size: 0.6rem; color: var(--ink-dim); text-align: center; padding-bottom: 0.3rem; text-transform: uppercase; }
.sl-cal-grid .day { aspect-ratio: 1; display: grid; place-items: center; font-family: var(--mono); font-size: 0.74rem; border-radius: var(--radius); cursor: pointer; color: var(--ink); }
.sl-cal-grid .day:hover { background: rgba(var(--glass-tint),0.12); }
.sl-cal-grid .day.muted { color: var(--ink-dim); opacity: 0.4; }
.sl-cal-grid .day.sel { background: var(--accent); color: var(--accent-ink); border: 2px solid rgb(var(--edge)); }

/* ============================================================
   ASPECT RATIO / CARD
   ============================================================ */
.sl-ratio { width: 100%; aspect-ratio: 16 / 9; border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); background: color-mix(in srgb, var(--accent) 30%, var(--bg-2)); display: grid; place-items: center; font-family: var(--mono); font-size: 0.68rem; color: var(--ink); }
.sl-card-demo { border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); box-shadow: 4px 4px 0 0 var(--hard-shadow); overflow: hidden; background: rgba(var(--glass-tint),0.05); }
.sl-card-demo .cd-media { aspect-ratio: 16/8; background: color-mix(in srgb, var(--accent) 34%, var(--bg-2)); border-bottom: var(--border-w) solid rgb(var(--edge)); }
.sl-card-demo .cd-body { padding: 0.9rem 1rem; }
.sl-card-demo .cd-body h4 { margin: 0 0 0.3rem; font-size: 1rem; }
.sl-card-demo .cd-body p { margin: 0 0 0.8rem; font-size: 0.82rem; color: var(--ink-dim); }

/* ============================================================
   OVERLAYS — dialog / sheet / popover backdrop
   ============================================================ */
.sl-overlay { position: fixed; inset: 0; z-index: 200; background: rgba(0,0,0,0.55); backdrop-filter: blur(3px); -webkit-backdrop-filter: blur(3px); display: grid; place-items: center; opacity: 0; pointer-events: none; transition: opacity 0.2s; }
.sl-overlay.open { opacity: 1; pointer-events: auto; }
.sl-dialog { width: min(440px, 92vw); padding: 1.6rem; background: var(--bg-2); border: var(--border-w) solid rgb(var(--edge)); border-radius: var(--radius); box-shadow: 10px 10px 0 0 var(--hard-shadow); transform: translateY(10px) scale(0.97); transition: transform 0.22s cubic-bezier(.2,.9,.2,1); }
.sl-overlay.open .sl-dialog { transform: none; }
.sl-dialog h3 { font-size: 1.3rem; margin: 0 0 0.5rem; }
.sl-dialog p { color: var(--ink-dim); font-size: 0.9rem; margin: 0 0 1.3rem; }
.sl-dialog .actions { display: flex; gap: 0.7rem; justify-content: flex-end; }
.sl-sheet-overlay { justify-items: end; place-items: stretch; }
.sl-sheet { position: fixed; top: 0; right: 0; bottom: 0; width: min(380px, 90vw); padding: 1.6rem; background: var(--bg-2); border-left: var(--border-w) solid rgb(var(--edge)); box-shadow: -10px 0 0 0 rgba(0,0,0,0.2); transform: translateX(100%); transition: transform 0.28s cubic-bezier(.2,.9,.2,1); }
.sl-sheet-overlay.open .sl-sheet { transform: none; }
.sl-sheet h3 { margin: 0 0 0.4rem; font-size: 1.2rem; }
.sl-sheet p { color: var(--ink-dim); font-size: 0.86rem; }

/* ============================================================
   TOAST
   ============================================================ */
.sl-toast-stack { position: fixed; bottom: 1.4rem; right: 1.4rem; z-index: 300; width: 300px; height: 0; }
.sl-toast {
  position: absolute; bottom: 0; right: 0; width: 100%; box-sizing: border-box;
  padding: 0.85rem 1rem; background: var(--bg-2);
  border: var(--border-w) solid rgb(var(--edge)); border-left: 6px solid var(--accent);
  border-radius: var(--radius); box-shadow: 5px 5px 0 0 var(--hard-shadow);
  display: flex; gap: 0.7rem; align-items: flex-start;
  --y: 0px; --s: 1;
  transform: translateX(125%);
  transform-origin: bottom right;
  transition: transform 0.4s cubic-bezier(.2,.9,.2,1), opacity 0.3s ease;
}
.sl-toast.show { transform: translateY(var(--y)) scale(var(--s)); }
.sl-toast .tt { font-weight: 700; font-size: 0.86rem; margin: 0 0 0.15rem; }
.sl-toast .td { font-size: 0.78rem; color: var(--ink-dim); margin: 0; }

/* ============================================================
   SHOWCASE — real products built on the system
   ============================================================ */
.show-feature { display: grid; grid-template-columns: 1.5fr 1fr; gap: 1.4rem; padding: 1.4rem; align-items: center; }
@media (max-width: 760px) { .show-feature { grid-template-columns: 1fr; } }
.show-browser { border: var(--border-w) solid rgb(var(--edge)); box-shadow: 6px 6px 0 0 var(--hard-shadow); overflow: hidden; background: var(--bg-2); }
.browser-bar { display: flex; align-items: center; gap: 0.5rem; padding: 0.55rem 0.7rem; border-bottom: var(--border-w) solid rgb(var(--edge)); background: rgba(var(--glass-tint),0.06); }
.browser-bar .tl { width: 11px; height: 11px; border: 1.5px solid rgb(var(--edge)); background: rgba(var(--glass-tint),0.15); flex: none; }
.browser-bar .url { margin-left: 0.6rem; font-family: var(--mono); font-size: 0.72rem; color: var(--ink-dim); padding: 0.2rem 0.7rem; border: 1.5px solid rgba(var(--edge),0.4); flex: 1; background: rgba(var(--glass-tint),0.04); }
.browser-shot { display: block; width: 100%; aspect-ratio: 16 / 10; }
.show-meta { display: flex; flex-direction: column; gap: 1rem; }
.show-name { font-weight: 700; }

/* ============================================================
   SITE PATTERNS — distilled from production SL consumers
   ============================================================ */
.sl-attribution {
  font-family: var(--mono);
  font-size: 0.72rem;
  color: var(--ink-dim);
}
.sl-attribution a {
  color: var(--ink);
  text-decoration: none;
  border-bottom: 1px solid var(--accent);
}
.sl-attribution a:hover { color: var(--accent); }

.sl-timeline {
  list-style: none;
  margin: 0;
  padding: 0;
}
.sl-timeline-item {
  position: relative;
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  gap: 0.85rem;
  padding: 0 0 1.15rem;
}
.sl-timeline-item:not(:last-child)::before {
  content: "";
  position: absolute;
  left: 7px;
  top: 16px;
  bottom: 0;
  width: 2px;
  background: rgb(var(--edge));
}
.sl-timeline-marker {
  position: relative;
  z-index: 1;
  width: 16px;
  height: 16px;
  border: var(--border-w) solid rgb(var(--edge));
  background: var(--accent);
  box-shadow: 2px 2px 0 0 var(--hard-shadow);
}
.sl-timeline-copy { min-width: 0; }
.sl-timeline-date {
  display: block;
  margin-bottom: 0.2rem;
  font-family: var(--mono);
  font-size: 0.68rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--ink-dim);
}
.sl-timeline-title { margin: 0; font-size: 1rem; }
.sl-timeline-body { margin-top: 0.25rem; color: var(--ink-dim); font-size: 0.86rem; line-height: 1.45; }

.sl-stepper {
  display: grid;
  grid-template-columns: repeat(var(--step-count, 3), minmax(0, 1fr));
  list-style: none;
  margin: 0;
  padding: 0;
}
.sl-step {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 0.55rem;
  min-width: 0;
}
.sl-step:not(:last-child)::after {
  content: "";
  position: absolute;
  left: 30px;
  right: 6px;
  top: 13px;
  height: 2px;
  background: rgb(var(--edge));
}
.sl-step-marker {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  flex: none;
  border: var(--border-w) solid rgb(var(--edge));
  background: var(--bg-2);
  color: var(--ink);
  font-family: var(--mono);
  font-size: 0.68rem;
  box-shadow: 2px 2px 0 0 var(--hard-shadow);
}
.sl-step-marker svg { width: 14px; height: 14px; }
.sl-step[data-status="complete"] .sl-step-marker,
.sl-step[data-status="current"] .sl-step-marker { background: var(--accent); color: var(--accent-ink); }
.sl-step-copy { position: relative; z-index: 1; display: flex; flex-direction: column; min-width: 0; padding: 0.1rem 0.35rem 0 0; background: var(--bg-2); }
.sl-step-copy strong { font-size: 0.78rem; }
.sl-step-copy > span { font-family: var(--mono); font-size: 0.62rem; color: var(--ink-dim); }
@media (max-width: 640px) {
  .sl-stepper { grid-template-columns: 1fr; gap: 0.75rem; }
  .sl-step:not(:last-child)::after { left: 13px; right: auto; top: 29px; bottom: -12px; width: 2px; height: auto; }
}

.sl-filter-toolbar {
  display: flex;
  align-items: end;
  flex-wrap: wrap;
  gap: 0.7rem;
  padding: 0.8rem;
  border: var(--border-w) solid rgb(var(--edge));
  background: rgba(var(--glass-tint), var(--glass-alpha));
  box-shadow: 4px 4px 0 0 var(--hard-shadow);
}
.sl-filter-group { display: flex; align-items: end; flex-wrap: wrap; gap: 0.55rem; min-width: 0; }
.sl-filter-summary { margin-left: auto; font-family: var(--mono); font-size: 0.68rem; color: var(--ink-dim); white-space: nowrap; }
@media (max-width: 640px) { .sl-filter-summary { width: 100%; margin-left: 0; } }

/* Field-sourced from the recurring command/intake surfaces in Dropship and Observatory. */
.sl-omnibar {
  display: grid;
  gap: 0.45rem;
  width: 100%;
  padding: 0.5rem;
  border: var(--border-w) solid rgb(var(--edge));
  background: rgba(var(--glass-tint), var(--glass-alpha));
  backdrop-filter: blur(var(--glass-blur)) saturate(150%);
  box-shadow: 5px 5px 0 0 var(--hard-shadow);
}
.sl-omnibar-attachments { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.sl-omnibar-attachment {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.25rem 0.4rem;
  border: 1.5px solid rgb(var(--edge));
  background: rgb(var(--glass-tint) / 0.08);
  font-family: var(--mono);
  font-size: 0.62rem;
  color: var(--ink-dim);
}
.sl-omnibar-attachment button {
  display: grid;
  place-items: center;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
}
.sl-omnibar-attachment svg { width: 12px; height: 12px; }
.sl-omnibar-row { display: flex; align-items: center; gap: 0.35rem; min-width: 0; }
.sl-omnibar-input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: var(--ink);
  font: 0.84rem var(--body);
}
.sl-omnibar-input::placeholder { color: var(--ink-dim); }
.sl-omnibar-icon,
.sl-omnibar-submit {
  width: 34px;
  height: 34px;
  flex: none;
  display: grid;
  place-items: center;
  border: var(--border-w) solid rgb(var(--edge));
  color: var(--ink);
  background: rgb(var(--glass-tint) / 0.06);
  cursor: pointer;
}
.sl-omnibar-icon svg,
.sl-omnibar-submit svg { width: 15px; height: 15px; }
.sl-omnibar-submit { background: var(--accent); color: var(--accent-ink); box-shadow: 2px 2px 0 0 var(--hard-shadow); }
.sl-omnibar-submit:active { transform: translate(2px, 2px); box-shadow: none; }
.sl-omnibar-status {
  font-family: var(--mono);
  font-size: 0.58rem;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent);
}
@media (max-width: 560px) { .sl-omnibar-status { display: none; } }

/* Field-sourced from the edge inspection surfaces in Cosmograph and Dropship. */
.sl-detail-panel {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: var(--border-w) solid rgb(var(--edge));
  background: rgba(var(--glass-tint), var(--glass-alpha));
  backdrop-filter: blur(var(--glass-blur)) saturate(150%);
  box-shadow: 5px 5px 0 0 var(--hard-shadow);
}
.sl-detail-panel-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  padding: 0.75rem 0.85rem;
  border-bottom: var(--border-w) solid rgb(var(--edge));
}
.sl-detail-panel-eyebrow {
  display: block;
  margin-bottom: 0.15rem;
  font-family: var(--mono);
  font-size: 0.58rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent);
}
.sl-detail-panel-title {
  margin: 0;
  font-family: var(--display);
  font-size: 1rem;
  line-height: 1.1;
}
.sl-detail-panel-body {
  padding: 0.85rem;
  color: var(--ink-dim);
  font-size: 0.82rem;
  line-height: 1.45;
}
.sl-detail-panel-footer {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  padding: 0.7rem 0.85rem;
  border-top: var(--border-w) solid rgb(var(--edge));
}

.sl-template { display: flex; min-height: 100%; flex-direction: column; gap: 1rem; }
.sl-template > .sl-site-content { display: flex; flex: 1; flex-direction: column; gap: 1rem; }
.sl-template-footer {
  margin-top: auto;
  padding-block: 1rem;
  border-top: var(--border-w) solid rgb(var(--edge));
}
.sl-template-guided > .sl-site-content {
  display: grid;
  grid-template-columns: minmax(220px, 0.7fr) minmax(0, 1.3fr);
  align-items: start;
}
.sl-template-immersive { min-height: 100dvh; }
.sl-template-immersive > main { position: relative; flex: 1; overflow: hidden; }
@media (max-width: 760px) { .sl-template-guided > .sl-site-content { grid-template-columns: 1fr; } }

/* Field-sourced from recurring social-proof cards on Interspace and Bumblebee. */
.sl-testimonial {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  margin: 0;
  padding: 1rem;
  border: var(--border-w) solid rgb(var(--edge));
  background: rgb(var(--glass-tint) / 0.08);
  box-shadow: 4px 4px 0 0 var(--hard-shadow);
}
.sl-testimonial-source {
  font-family: var(--mono);
  font-size: 0.62rem;
  font-weight: 700;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  color: var(--accent);
}
.sl-testimonial-quote {
  margin: 0;
  font-family: var(--body);
  font-size: 0.9rem;
  line-height: 1.55;
  color: var(--ink);
}
.sl-testimonial-author {
  padding-top: 0.65rem;
  border-top: 1px solid rgb(var(--edge) / 0.3);
  font-family: var(--display);
  font-size: 0.78rem;
  font-weight: 700;
}
.sl-testimonial-meta {
  display: block;
  margin-top: 0.15rem;
  font-family: var(--mono);
  font-size: 0.6rem;
  font-weight: 400;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-dim);
}

/* Field-sourced from the recurring trust and portfolio identity walls. */
.sl-logo-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(90px, 1fr));
  gap: 0.55rem;
}
.sl-logo-tile {
  display: grid;
  min-height: 86px;
  place-items: center;
  align-content: center;
  gap: 0.45rem;
  padding: 0.65rem;
  border: var(--border-w) solid rgb(var(--edge));
  background: rgb(var(--glass-tint) / 0.08);
  box-shadow: 3px 3px 0 0 var(--hard-shadow);
}
.sl-logo-mark {
  display: grid;
  width: 2.5rem;
  height: 2.5rem;
  place-items: center;
  background: var(--accent);
  color: var(--accent-ink);
  font-family: var(--display);
  font-weight: 800;
}
.sl-logo-label {
  font-family: var(--mono);
  font-size: 0.58rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ink-dim);
}
/* Persistent portfolio identity cards: the default for company and venture grids. */
.sl-portfolio-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 210px), 1fr));
  gap: 1rem;
}
.sl-portfolio-card {
  display: flex;
  min-height: 290px;
  flex-direction: column;
  overflow: hidden;
  border: var(--border-w) solid rgb(var(--edge));
  border-radius: var(--radius);
  background: var(--bg-2);
  color: var(--ink);
  box-shadow: 4px 4px 0 0 var(--hard-shadow);
  text-decoration: none;
  transition: transform var(--motion-fast) var(--ease-liquid), box-shadow var(--motion-fast) var(--ease-liquid);
}
.sl-portfolio-card[href] { cursor: pointer; }
.sl-portfolio-card[href]:hover,
.sl-portfolio-card[href]:focus-visible {
  transform: translate(-1px, -1px);
  box-shadow: 6px 6px 0 0 var(--hard-shadow);
}
.sl-portfolio-card[href]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 4px;
}
.sl-portfolio-card-media {
  position: relative;
  display: grid;
  min-height: 9.5rem;
  flex: 0 0 9.5rem;
  place-items: center;
  padding: 1.25rem;
  border-bottom: var(--border-w) solid rgb(var(--edge));
  background: var(--bg-2);
}
.sl-portfolio-card-logo {
  display: grid;
  min-width: 4.25rem;
  min-height: 4.25rem;
  place-items: center;
  color: var(--ink);
  font-family: var(--display);
  font-size: clamp(1.35rem, 3vw, 2rem);
  font-weight: 900;
  letter-spacing: -0.04em;
}
.sl-portfolio-card-logo > img,
.sl-portfolio-card-logo > svg {
  display: block;
  width: min(100%, 11rem);
  max-height: 5.5rem;
  object-fit: contain;
}
.sl-portfolio-card-body {
  display: flex;
  min-height: 9.5rem;
  flex: 1;
  flex-direction: column;
  padding: 1rem;
  background: var(--neg);
  color: var(--neg-ink);
}
.sl-portfolio-card-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
}
.sl-portfolio-card-media > .sl-portfolio-card-tags {
  position: absolute;
  inset: 0.65rem 0.65rem auto;
  z-index: 1;
}
.sl-portfolio-card-body > .sl-portfolio-card-tags { margin-bottom: 0.7rem; }
.sl-portfolio-card-tag {
  padding: 0.28rem 0.45rem;
  border: 1px solid rgb(var(--edge));
  background: color-mix(in srgb, var(--neg) 80%, #000000);
  color: var(--neg-ink);
  font-family: var(--mono);
  font-size: 0.56rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  text-transform: uppercase;
  box-shadow: 2px 2px 0 0 var(--hard-shadow);
}
.sl-portfolio-card-title {
